// Package: Azure.Storage.Blobs
// Install: dotnet add package Azure.Storage.Blobs

using Azure.Storage.Blobs;
using Azure.Storage.Blobs.Models;

public class BlobStorageService
{
    private readonly BlobContainerClient _container;

    public BlobStorageService(string connectionString, string containerName = "uploads")
    {
        var service = new BlobServiceClient(connectionString);
        _container = service.GetBlobContainerClient(containerName);
    }

    public async Task UploadAsync(string localPath, string blobName, CancellationToken ct = default)
    {
        try
        {
            await _container.CreateIfNotExistsAsync(PublicAccessType.None, ct);
            var blob = _container.GetBlobClient(blobName);
            await blob.UploadAsync(localPath, overwrite: true, ct);
            Console.WriteLine($"Uploaded {blobName}");
        }
        catch (RequestFailedException ex)
        {
            Console.WriteLine($"Upload failed: {ex.Status} - {ex.Message}");
            throw;
        }
    }

    public async Task DownloadAsync(string blobName, string destinationPath, CancellationToken ct = default)
    {
        try
        {
            var blob = _container.GetBlobClient(blobName);
            var download = await blob.DownloadAsync(ct);
            await using var stream = File.OpenWrite(destinationPath);
            await download.Value.Content.CopyToAsync(stream, ct);
            Console.WriteLine($"Downloaded {blobName} to {destinationPath}");
        }
        catch (RequestFailedException ex) when (ex.Status == 404)
        {
            Console.WriteLine($"Blob {blobName} not found");
            throw;
        }
    }
}

// Usage with actual sample data
var service = new BlobStorageService("DefaultEndpointsProtocol=https;AccountName=demostorageaccount;...", "uploads");
await service.UploadAsync("report.pdf", "report-2024.pdf");
await service.DownloadAsync("report-2024.pdf", "report-copy.pdf");

// Expected output:
// Uploaded report-2024.pdf
// Downloaded report-2024.pdf to report-copy.pdf

// List all blobs in the 'uploads' container
await foreach (var blobItem in container.GetBlobsAsync())
{
    Console.WriteLine($"{blobItem.Name} - {blobItem.Properties.ContentLength} bytes");
}

// Delete blob with snapshots included
await blob.DeleteIfExistsAsync(DeleteSnapshotsOption.IncludeSnapshots);

// Expected output (if blobs exist):
// report-2024.pdf - 1048576 bytes
// invoices/jan.csv - 2048 bytes

// Package: Azure.Storage.Blobs
// Install: dotnet add package Azure.Storage.Blobs

using Azure.Storage.Blobs;
using Azure.Storage.Blobs.Models;

public class BlobSasService
{
    private readonly BlobContainerClient _container;

    public BlobSasService(BlobContainerClient container) => _container = container;

    public Uri GenerateReadSasUri(string blobName, TimeSpan? lifetime = null)
    {
        lifetime ??= TimeSpan.FromHours(1);
        var blob = _container.GetBlobClient(blobName);

        var sasBuilder = new BlobSasBuilder
        {
            BlobContainerName = _container.Name,
            BlobName = blobName,
            Resource = "b",
            ExpiresOn = DateTimeOffset.UtcNow.Add(lifetime.Value)
        };

        sasBuilder.SetPermissions(BlobSasPermissions.Read);

        var sasUri = blob.GenerateSasUri(sasBuilder);
        Console.WriteLine($"Generated SAS URI for {blobName}: {sasUri}");
        return sasUri;
    }
}

// Usage
var blobUri = new Uri("https://demostorageaccount.blob.core.windows.net/uploads");
var service = new BlobSasService(new BlobContainerClient(blobUri, new DefaultAzureCredential()));
Uri sas = service.GenerateReadSasUri("report-2024.pdf");

// Expected output:
// Generated SAS URI for report-2024.pdf: https://demostorageaccount.blob.core.windows.net/uploads/report-2024.pdf?<sas-token>
